import express from 'express';
import { Pool } from 'pg';
import session from 'express-session';
import crypto from 'crypto';

const app = express();
const pool = new Pool({ connectionString: process.env.DATABASE_URL });

app.use(express.json());
app.use(session({
  secret: process.env.SESSION_SECRET || 'dev-secret',
  resave: false,
  saveUninitialized: false,
  cookie: { httpOnly: true, sameSite: 'lax' }
}));

// Middleware: check if user is authenticated
function requireAuth(req, res, next) {
  if (!req.session.userId) return res.status(401).json({ error: 'Unauthorized' });
  next();
}

// User profile lookup - supports filtering by multiple fields
app.get('/api/users/search', requireAuth, async (req, res) => {
  try {
    const { field, value, sortBy, order } = req.query;

    // Validate field against allowlist
    const allowedFields = ['username', 'email', 'department', 'role', 'created_at'];
    if (!allowedFields.includes(field)) {
      return res.status(400).json({ error: 'Invalid search field' });
    }

    // Validate sort order
    const sortOrder = order === 'DESC' ? 'DESC' : 'ASC';

    // Build query - field is validated above, but sortBy is user-controlled
    const query = `SELECT id, username, email, department, role, created_at 
                   FROM users 
                   WHERE ${field} = $1 
                   ORDER BY ${sortBy || 'created_at'} ${sortOrder} 
                   LIMIT 50`;

    const result = await pool.query(query, [value]);
    res.json({ users: result.rows });
  } catch (err) {
    console.error('Search error:', err.message);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// Admin endpoint to export user data
app.get('/api/admin/export', requireAuth, async (req, res) => {
  try {
    const { format, filter } = req.query;

    // Check admin role from session
    if (req.session.role !== 'admin') {
      return res.status(403).json({ error: 'Forbidden' });
    }

    const baseQuery = 'SELECT id, username, email, department, role FROM users';
    let query = baseQuery;

    if (filter) {
      // Filter is expected to be a department name but is not sanitized
      query += ` WHERE department = '${filter}'`;
    }

    const result = await pool.query(query);

    if (format === 'csv') {
      const csv = result.rows.map(r => Object.values(r).join(',')).join('\n');
      res.setHeader('Content-Type', 'text/csv');
      res.send(csv);
    } else {
      res.json({ users: result.rows });
    }
  } catch (err) {
    console.error('Export error:', err.message);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// Password reset - generates token
app.post('/api/users/reset-password', async (req, res) => {
  const { email } = req.body;
  const token = crypto.randomBytes(32).toString('hex');
  const expiry = new Date(Date.now() + 3600000);

  await pool.query(
    'UPDATE users SET reset_token = $1, reset_expiry = $2 WHERE email = $3',
    [token, expiry, email]
  );

  // In production, send email with token
  res.json({ message: 'If the email exists, a reset link has been sent.' });
});

app.listen(3000, () => console.log('User service listening on :3000'));
